# เพิ่ม hosts สำหรับ hanaitspareparts\n$hostsPath = "$env:SystemRoot\System32\drivers\etc\hosts"\n$entry = "127.0.0.1 hanaitspareparts"\n\n# ตรวจสอบว่ามีอยู่แล้วหรือยัง\nif (-not (Select-String -Path $hostsPath -Pattern "127.0.0.1\s+hanaitspareparts")) {\n    Add-Content -Path $hostsPath -Value $entry\n    Write-Host "เพิ่ม hosts สำเร็จ"\n} else {\n    Write-Host "มี entry นี้ใน hosts แล้ว"\n}\n